gr.query();

var count = 0;
while (gr.next()) {
  gr.state = 7; // Closed
  gr.close_notes = 'Auto-closed after 7 days in resolved state';
  gr.setWorkflow(false);
  gr.autoSysFields(false);
  gr.update();
  count++;
}
gs.info('Auto-closed ' + count + ' stale incidents');

// Process in batches of 500
var batchSize = 500;
var processed = 0;
var hasMore = true;

while (hasMore) {
  var gr = new GlideRecord('u_temp_records');
  gr.addQuery('processed', false);
  gr.setLimit(batchSize);
  gr.query();

  if (!gr.hasNext()) {
    hasMore = false;
    break;
  }

  while (gr.next()) {
    // Process record
    gr.setValue('processed', true);
    gr.setWorkflow(false);
    gr.update();
    processed++;
  }
  gs.info('Processed batch, total: ' + processed);
}
gs.info('Job complete. Total processed: ' + processed);

