// POST /api/x_app/myapi/incidents
(function process(request, response) {
  var body = request.body.data;

  // Validate required fields
  if (!body.short_description) {
    response.setStatus(400);
    response.setBody({error: 'short_description is required'});
    return;
  }

  var gr = new GlideRecord('incident');
  gr.initialize();
  gr.setValue('short_description', body.short_description);
  gr.setValue('description', body.description || '');
  gr.setValue('urgency', body.urgency || 3);
  gr.setValue('impact', body.impact || 3);
  gr.setValue('caller_id', gs.getUserID());

  var sysId = gr.insert();
  if (sysId) {
    response.setStatus(201);
    response.setHeader('Location', '/api/x_app/myapi/incidents/' + sysId);
    response.setBody({sys_id: sysId, number: gr.getValue('number')});
  } else {
    response.setStatus(500);
    response.setBody({error: 'Failed to create incident'});
  }
})(request, response);

// GET /api/x_app/myapi/incidents?active=true&limit=10
(function process(request, response) {
  var active = request.queryParams.active ? request.queryParams.active[0] : 'true';
  var limit = request.queryParams.limit ? parseInt(request.queryParams.limit[0]) : 20;
  var offset = request.queryParams.offset ? parseInt(request.queryParams.offset[0]) : 0;

  var gr = new GlideRecord('incident');
  gr.addQuery('active', active);
  gr.orderByDesc('sys_created_on');
  gr.chooseWindow(offset, offset + limit);
  gr.query();

  var results = [];
  while (gr.next()) {
    results.push({
      sys_id: gr.getUniqueValue(),
      number: gr.getValue('number'),
      short_description: gr.getValue('short_description'),
      state: gr.getDisplayValue('state')
    });
  }

  response.setStatus(200);
  response.setHeader('X-Total-Count', String(gr.getRowCount()));
  response.setBody({result: results, count: results.length});
})(request, response);

