function cloneRecord(sourceGR, targetTable) {
  var target = new GlideRecord(targetTable || sourceGR.getTableName());
  target.initialize();
  var fields = sourceGR.getFields();
  for (var i = 0; i < fields.size(); i++) {
    var field = fields.get(i);
    var name = field.getName();
    if (name == 'sys_id' || name.startsWith('sys_')) continue;
    target.setValue(name, sourceGR.getValue(name));
  }
  return target.insert();
}

