function bulkUpdate(table, query, fieldValues, options) {
  options = options || {};
  var gr = new GlideRecord(table);
  gr.addEncodedQuery(query);
  gr.query();
  var count = 0;
  while (gr.next()) {
    for (var field in fieldValues) {
      gr.setValue(field, fieldValues[field]);
    }
    if (options.skipWorkflow) gr.setWorkflow(false);
    if (options.skipAudit) gr.autoSysFields(false);
    gr.update();
    count++;
  }
  return count;
}

