function grToJSON(gr, fields) {
  var obj = { sys_id: gr.getUniqueValue() };
  if (fields) {
    fields.forEach(function(f) {
      obj[f] = gr.getValue(f);
      obj[f + '_display'] = gr.getDisplayValue(f);
    });
  } else {
    var flds = gr.getFields();
    for (var i = 0; i < flds.size(); i++) {
      var name = flds.get(i).getName();
      if (!name.startsWith('sys_') || name == 'sys_id') {
        obj[name] = gr.getValue(name);
      }
    }
  }
  return obj;
}

