function buildQuery(filters) {
  var parts = [];
  for (var field in filters) {
    var val = filters[field];
    if (Array.isArray(val)) {
      parts.push(field + 'IN' + val.join(','));
    } else if (val === null) {
      parts.push(field + 'ISEMPTY');
    } else if (typeof val === 'object' && val.op) {
      parts.push(field + val.op + val.value);
    } else {
      parts.push(field + '=' + val);
    }
  }
  return parts.join('^');
}

