function businessDaysBetween(startStr, endStr) {
  var start = new GlideDateTime(startStr);
  var end = new GlideDateTime(endStr);
  var count = 0;
  var current = new GlideDateTime(start);
  while (current.before(end)) {
    var dow = current.getDayOfWeekLocalTime();
    if (dow >= 2 && dow <= 6) count++; // Mon=2, Fri=6
    current.addDaysLocalTime(1);
  }
  return count;
}

