function formatDate(gdtStr, format) {
  var gdt = new GlideDateTime(gdtStr);
  switch (format) {
    case 'short': return gdt.getDate().getByFormat('MM/dd/yyyy');
    case 'long': return gdt.getDate().getByFormat('MMMM dd, yyyy');
    case 'relative': return getRelativeTime(gdt);
    default: return gdt.getDisplayValue();
  }
}

function getRelativeTime(gdt) {
  var diff = GlideDateTime.subtract(gdt, new GlideDateTime());
  var days = diff.getDayPart();
  if (days == 0) return 'Today';
  if (days == 1) return 'Yesterday';
  if (days < 7) return days + ' days ago';
  if (days < 30) return Math.floor(days / 7) + ' weeks ago';
  return Math.floor(days / 30) + ' months ago';
}

function isBusinessHours(scheduleId) {
  var sched = new GlideSchedule(scheduleId);
  if (!sched.isValid()) return true; // Default to true if no schedule
  return sched.isInSchedule(new GlideDateTime());
}

