function addBusinessDays(startStr, numDays) {
  var dt = new GlideDateTime(startStr);
  var added = 0;
  while (added < numDays) {
    dt.addDaysLocalTime(1);
    var dow = dt.getDayOfWeekLocalTime();
    if (dow >= 2 && dow <= 6) added++;
  }
  return dt;
}

