function restCallWithRetry(endpoint, method, body, maxRetries) {
  maxRetries = maxRetries || 3;
  var lastError = '';
  for (var attempt = 1; attempt <= maxRetries; attempt++) {
    try {
      var rm = new sn_ws.RESTMessageV2();
      rm.setEndpoint(endpoint);
      rm.setHttpMethod(method);
      rm.setRequestHeader('Content-Type', 'application/json');
      rm.setRequestHeader('Accept', 'application/json');
      if (body) rm.setRequestBody(JSON.stringify(body));
      var resp = rm.execute();
      var status = resp.getStatusCode();
      if (status >= 200 && status < 300) {
        return { success: true, data: JSON.parse(resp.getBody()), status: status };
      }
      if (status < 500) {
        return { success: false, error: resp.getBody(), status: status };
      }
      lastError = 'HTTP ' + status;
    } catch (e) {
      lastError = e.getMessage();
    }
    if (attempt < maxRetries) gs.sleep(1000 * attempt);
  }
  return { success: false, error: 'Max retries exceeded: ' + lastError };
}

