function fetchAllPages(baseUrl, headers) {
  var allResults = [];
  var offset = 0;
  var limit = 100;
  var hasMore = true;
  while (hasMore) {
    var rm = new sn_ws.RESTMessageV2();
    rm.setEndpoint(baseUrl + '?sysparm_limit=' + limit + '&sysparm_offset=' + offset);
    rm.setHttpMethod('GET');
    for (var h in headers) rm.setRequestHeader(h, headers[h]);
    var resp = rm.execute();
    var data = JSON.parse(resp.getBody());
    allResults = allResults.concat(data.result);
    offset += limit;
    hasMore = data.result.length === limit;
  }
  return allResults;
}

