function copyAttachments(sourceTable, sourceSysId, targetTable, targetSysId) {
  var sa = new GlideSysAttachment();
  var attachments = sa.getAttachments(sourceTable, sourceSysId);
  var count = 0;
  while (attachments.next()) {
    var content = sa.getContentBase64(attachments);
    sa.writeBase64(
      targetTable + ':' + targetSysId,
      attachments.getValue('file_name'),
      attachments.getValue('content_type'),
      content
    );
    count++;
  }
  return count;
}

