function getManagerChain(userId, maxDepth) {
  var chain = [];
  var currentId = userId;
  var depth = 0;
  maxDepth = maxDepth || 5;

  while (currentId && depth < maxDepth) {
    var user = new GlideRecord('sys_user');
    if (!user.get(currentId)) break;
    var managerId = user.getValue('manager');
    if (!managerId || managerId == currentId) break;
    chain.push({
      sys_id: managerId,
      name: user.manager.getDisplayValue()
    });
    currentId = managerId;
    depth++;
  }
  return chain;
}

