  if (gr.next()) {
    return {
      type: gr.getValue('internal_type'),
      label: gr.getValue('column_label'),
      maxLength: gr.getValue('max_length'),
      mandatory: gr.getValue('mandatory') == 'true',
      readOnly: gr.getValue('read_only') == 'true',
      reference: gr.getValue('reference'),
      defaultValue: gr.getValue('default_value')
    };
  }
  return null;
}

