function getRelatedCIs(ciSysId, relType) {
  var results = [];
  var gr = new GlideRecord('cmdb_rel_ci');
  var qc = gr.addQuery('parent', ciSysId);
  qc.addOrCondition('child', ciSysId);
  if (relType) gr.addQuery('type.name', relType);
  gr.query();
  while (gr.next()) {
    var related = (gr.getValue('parent') == ciSysId) 
      ? gr.getValue('child') 
      : gr.getValue('parent');
    results.push({
      sys_id: related,
      type: gr.type.getDisplayValue(),
      direction: (gr.getValue('parent') == ciSysId) ? 'outbound' : 'inbound'
    });
  }
  return results;
}

