function getAffectedServices(ciSysId) {
  var services = [];
  var visited = {};

  function walk(id, depth) {
    if (visited[id] || depth > 5) return;
    visited[id] = true;
    var gr = new GlideRecord('cmdb_rel_ci');
    gr.addQuery('child', id);
    gr.addQuery('type.name', 'Depends on::Used by');
    gr.query();
    while (gr.next()) {
      var parentId = gr.getValue('parent');
      var parentGR = new GlideRecord('cmdb_ci_service');
      if (parentGR.get(parentId)) {
        services.push({ sys_id: parentId, name: parentGR.getValue('name') });
      }
      walk(parentId, depth + 1);
    }
  }

  walk(ciSysId, 0);
  return services;
}

