function findCI(identifier) {
  var tables = ['cmdb_ci_server', 'cmdb_ci_computer', 'cmdb_ci_vm_instance', 'cmdb_ci'];
  var fields = ['name', 'ip_address', 'serial_number', 'asset_tag'];

  for (var t = 0; t < tables.length; t++) {
    for (var f = 0; f < fields.length; f++) {
      var gr = new GlideRecord(tables[t]);
      if (gr.isValidField(fields[f])) {
        gr.addQuery(fields[f], identifier);
        gr.setLimit(1);
        gr.query();
        if (gr.next()) return gr;
      }
    }
  }
  return null;
}

