  gr.addQuery('workflow_state', 'published');
  gr.addQuery('active', true);
  var qc = gr.addQuery('short_description', 'CONTAINS', query);
  qc.addOrCondition('text', 'CONTAINS', query);
  gr.setLimit(limit || 10);
