var Logger = function(source) {
  this.source = source;
  this.prefix = '[' + source + '] ';
};
Logger.prototype.info = function(msg) { gs.info(this.prefix + msg); };
Logger.prototype.warn = function(msg) { gs.warn(this.prefix + msg); };
Logger.prototype.error = function(msg) { gs.error(this.prefix + msg); };
Logger.prototype.debug = function(msg) { gs.debug(this.prefix + msg); };
Logger.prototype.startTimer = function(label) {
  this._timers = this._timers || {};
  this._timers[label] = new Date().getTime();
};
Logger.prototype.endTimer = function(label) {
  if (this._timers && this._timers[label]) {
    var ms = new Date().getTime() - this._timers[label];
    this.info(label + ': ' + ms + 'ms');
    return ms;
  }
};

