function extractTickets(text) {
  var patterns = {
    incident: /INC\d{7,}/g,
    change: /CHG\d{7,}/g,
    problem: /PRB\d{7,}/g,
    request: /REQ\d{7,}/g,
    ritm: /RITM\d{7,}/g,
    task: /TASK\d{7,}/g
  };
  var found = {};
  for (var type in patterns) {
    var matches = text.match(patterns[type]);
    if (matches) found[type] = matches;
  }
  return found;
}

