var tickets = extractTickets(email.body_text);
if (tickets.incident) {
  gs.info('Found incidents: ' + tickets.incident.join(', '));
}

function isValidIP(ip) {
  var regex = /^(25[0-5]|2[0-4]\d|[01]?\d\d?)\.(25[0-5]|2[0-4]\d|[01]?\d\d?)\.(25[0-5]|2[0-4]\d|[01]?\d\d?)\.(25[0-5]|2[0-4]\d|[01]?\d\d?)$/;
  return regex.test(ip);
}

// Usage:
if (!isValidIP(current.getValue('u_ip_address'))) {
  gs.addErrorMessage('Invalid IP address');
}

function stripHTML(html) {
  return html.replace(/<[^>]*>/g, '').replace(/&nbsp;/g, ' ').trim();
}

